$m1_l14_t6_starter$, $m1_l14_t6_solution$from datetime import date

def deadline_status(today, deadline):
    today_date = date.fromisoformat(today)
    deadline_date = date.fromisoformat(deadline)
    if deadline_date < today_date:
        return 'overdue'
    if deadline_date == today_date:
        return 'today'
    return 'future'
