    pass
$m1_l18_t5_starter$, $m1_l18_t5_solution$class TemporaryFlag:
    def __init__(self, state):
        self.state = state
        self.previous = None
    def __enter__(self):
        self.previous = self.state.get("enabled", False)
        self.state["enabled"] = True
        return self.state
    def __exit__(self, exc_type, exc, tb):
        self.state["enabled"] = self.previous
        return False
