    pass
$m2_l7_t9_starter$, $m2_l7_t9_solution$from typing import Protocol

class CacheLike(Protocol):
    def get(self, key: str) -> object | None: ...
    def set(self, key: str, value: object) -> None: ...

def remember(cache: CacheLike, key: str, value: object) -> object:
    current = cache.get(key)
    if current is None:
        cache.set(key, value)
        return value
    return current
