INSERT INTO tasks(lesson_id, title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy, is_published)
SELECT lr.lesson_id, ts.title, ts.statement_md, ts.starter_code, ts.solution_code, ts.difficulty, ts.xp_reward, ts.topic, ts.language, ts.source_policy, TRUE
FROM lesson_ref lr
CROSS JOIN task_seed ts
ON CONFLICT (lesson_id, title) DO UPDATE
SET statement_md = EXCLUDED.statement_md,
    starter_code = EXCLUDED.starter_code,
    solution_code = EXCLUDED.solution_code,
    difficulty = EXCLUDED.difficulty,
    xp_reward = EXCLUDED.xp_reward,
    topic = EXCLUDED.topic,
    language = EXCLUDED.language,
    source_policy = EXCLUDED.source_policy,
    is_published = TRUE,
    updated_at = NOW();

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 2 AND l.position = 18
)
DELETE FROM task_test_cases tc
USING tasks t, lesson_ref lr
WHERE tc.task_id = t.id
  AND t.lesson_id = lr.lesson_id
  AND t.is_published = TRUE;
WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 2 AND l.position = 18
), task_ref AS (
  SELECT t.id AS task_id, t.title
  FROM tasks t
  JOIN lesson_ref lr ON lr.lesson_id = t.lesson_id
  WHERE t.is_published = TRUE
), block_seed(position, block_type, title, content_md, task_title, quiz_payload) AS (
  VALUES
  (1, $m2_l18_b1_type$theory$m2_l18_b1_type$, $m2_l18_b1_title$Что это$m2_l18_b1_title$, $m2_l18_b1_content$### Что это
Тема «Логирование» разбирает один конкретный механизм. Важно понять не только синтаксис, но и какое состояние или контракт меняется после выполнения.

### Зачем это нужно
Без темы «Логирование» легко получить код, который запускается, но проверяет неверный контракт именно в этом уроке.

### Где это встречается в backend
В backend тема «Логирование» помогает держать поведение явным: результат можно проверить, объяснить ревьюеру и безопасно изменить.

### Минимальная схема
```python
def inspect_logirovanie_case(raw):
    cleaned = str(raw).strip()
    return {"topic": "Логирование", "value": cleaned, "empty": cleaned == ""}
```

### Разбор схемы
Прочитай пример сверху вниз. Первая значимая строка задаёт границу темы «Логирование». Следующие строки показывают действие, которое меняет данные, состояние, запрос или артефакт. Последняя проверяемая строка показывает, как убедиться, что именно этот навык сработал.

### Частая ошибка
Частая ошибка в теме «Логирование» — взять похожий пример из соседнего урока и проверить не тот навык. Перед задачей сравни method, path, table, объект, файл или команду с темой урока.

