INSERT INTO task_test_cases(task_id, input_data, expected_output, is_hidden, position)
SELECT tr.task_id, ts.input_data, ts.expected_output, ts.is_hidden, ts.position
FROM test_seed ts
JOIN task_ref tr ON tr.title = ts.task_title
ON CONFLICT (task_id, position) DO UPDATE
SET input_data = EXCLUDED.input_data,
    expected_output = EXCLUDED.expected_output,
    is_hidden = EXCLUDED.is_hidden;
